"use client";

import { usePendingTaskCreates } from "@/hooks/use-create-task-pending";

export function PendingTaskRows() {
  const pending = usePendingTaskCreates();

  return pending.map(item => (
    <tr key={item.submittedAt} aria-busy="true">
      <td>{item.input.title}</td>
      <td>Pending creation</td>
      <td>{item.input.priority ?? "MEDIUM"}</td>
    </tr>
  ));
}

"use client";

import { useTaskStatusOptimistic } from "@/hooks/use-task-status-optimistic";
import type { TaskStatus } from "@/lib/api/task-types";

type Props = {
  taskId: string;
  status: TaskStatus;
};

export function TaskStatusButton({ taskId, status }: Props) {
  const mutation = useTaskStatusOptimistic(taskId);

  const visibleStatus = mutation.isPending
    ? mutation.variables
    : status;

  const nextStatus: TaskStatus =
    visibleStatus === "DONE" ? "IN_PROGRESS" : "DONE";

"use client";

import { useIsMutating } from "@tanstack/react-query";

export function TaskSavingIndicator() {
  const count = useIsMutating({ mutationKey: ["tasks", "mutation"] });

  if (count === 0) return null;

  return (
    <span role="status" aria-live="polite">
      Saving {count === 1 ? "change" : `${count} changes`}...
    </span>
  );
}

"use client";

import { useMutation, useMutationState } from "@tanstack/react-query";
import { createTask } from "@/lib/api/task-mutations";
import { taskKeys } from "@/lib/query/task-keys";
import { taskMutationKeys } from "@/lib/query/task-mutation-keys";
import type { CreateTaskInput } from "@repo/validators/tasks";

export function useCreateTask() {
  return useMutation({
    mutationKey: taskMutationKeys.create(),
    mutationFn: createTask,
    onSettled: async (_data, _error, _variables, _result, context) => {
      await context.client.invalidateQueries({
        queryKey: taskKeys.lists(),
      });
    },
  });
}

