export function useTaskStatusOptimistic(taskId: string) {
  return useMutation({
    mutationKey: taskMutationKeys.updateStatus(taskId),
    scope: { id: `task-status:${taskId}` },

    mutationFn: (status: TaskStatus) =>
      updateTask(taskId, { status }),

    onMutate: async (status, context) => {
      const key = taskKeys.detail(taskId);

      await context.client.cancelQueries({ queryKey: key });

export const taskMutationKeys = {
  all: ["tasks", "mutation"] as const,
  create: () => [...taskMutationKeys.all, "create"] as const,
  updateStatus: (taskId: string) =>
    [...taskMutationKeys.all, "status", taskId] as const,
};
